('ITM-CAM-1011', 'Security Camera Housing with Pole', 'CAM-9001-A', 'Security camera housing with a spun-metal front-shell (DEVO), aluminium 2.4m CHS pole with drilled mounting holes, in-house blow-molded acrylic lens and lathe-turned spacer ring. Coated finish and manual line assembly.', '[{"materialId":"MAT-2026-0005","name":"DEVO Metal Spun Housing Front-Shell","qtyNeeded":1},{"materialId":"MAT-2026-0006","name":"Aluminium Pole 2.4m CHS Profile","qtyNeeded":1},{"materialId":"MAT-2026-0007","name":"EPLAS Acrylic Plastic Sheet Clear","qtyNeeded":0.1},{"materialId":"MAT-2026-0008","name":"Acetal Polymer Round Lathe Rod Black","qtyNeeded":0.1}]', '[{"type":"CHS","description":"Mounting Pole Stem","size":"50mm CHS x 2.4m","lengthMm":2400,"qty":1},{"type":"Plate","description":"Acrylic Lens Sheet raw prep","size":"4mm Thick Acrylic","lengthMm":300,"qty":1}]', '[{"name":"Final Assembly Line Routing","estimatedHours":2.5,"sequence":1},{"name":"QMS Compliance Verify Stamp","estimatedHours":1,"sequence":2}]', '[{"name":"CAM-HOUSING-3D-EXPLODED.pdf","fileType":"PDF","fileSize":"4.2 MB","uploadDate":"2026-06-13","uploadedBy":"Robert Vance","designVersion":"Rev 1"}]', '[{"childItemId":"ITM-CAM-PART-DEVO","qty":1},{"childItemId":"ITM-CAM-PART-POLE","qty":1},{"childItemId":"ITM-CAM-PART-LENS","qty":1},{"childItemId":"ITM-CAM-PART-SPACER","qty":1}]', '2026-06-13', 'Robert Vance'),
('ITM-CAM-PART-DEVO', 'DEVO Metal Spun Front-Shell', 'CAM-PART-DEVO', 'Sourced from Queensland Metal Spinners. Requires preparation, surface treatment, and architectural powder coating finish.', '[{"materialId":"MAT-2026-0005","name":"DEVO Metal Spun Housing Front-Shell","qtyNeeded":1}]', '[]', '[{"name":"Powder Coating (DEVO & Pole)","estimatedHours":2,"sequence":1}]', '[{"name":"DEVO-SPUN-SHELL-REV2.pdf","fileType":"PDF","fileSize":"2.5 MB","uploadDate":"2026-06-13","uploadedBy":"Robert Vance","designVersion":"Rev 2"}]', '[]', '2026-06-13', 'Robert Vance'),
('ITM-CAM-PART-POLE', '2.4m CHS Aluminium Mounting Pole', 'CAM-PART-POLE', 'Aluminium support stem. Requires CNC mill drilling for secure bracket holes and exterior powder coating.', '[{"materialId":"MAT-2026-0006","name":"Aluminium Pole 2.4m CHS Profile","qtyNeeded":1}]', '[{"type":"CHS","description":"Mounting Pole Stem","size":"50mm CHS x 2.4m","lengthMm":2400,"qty":1}]', '[{"name":"CNC Drilling & Deburring","estimatedHours":1.5,"sequence":1},{"name":"Powder Coating (DEVO & Pole)","estimatedHours":2,"sequence":2}]', '[{"name":"ALLY-POLE-2.4M-DRILLING-REVB.dxf","fileType":"DXF","fileSize":"1.1 MB","uploadDate":"2026-06-13","uploadedBy":"Robert Vance","designVersion":"Rev B"}]', '[]', '2026-06-13', 'Robert Vance'),
('ITM-CAM-PART-LENS', 'Blown Acrylic Camera Lens Dome', 'CAM-PART-LENS', 'Optically clear dome lens. Cut to size from EPLAS sheets, thermo blow-molded in-house, prepped, and drilled with four mounting alignment holes.', '[{"materialId":"MAT-2026-0007","name":"EPLAS Acrylic Plastic Sheet Clear","qtyNeeded":0.1}]', '[{"type":"Plate","description":"Acrylic Lens Sheet raw prep","size":"4mm Thick Acrylic","lengthMm":300,"qty":1}]', '[{"name":"Abrasive Cutoff","estimatedHours":0.5,"sequence":1},{"name":"In-House Blow Mold Lens","estimatedHours":1,"sequence":2},{"name":"Acrylic Lens Finishing & Drilling","estimatedHours":1,"sequence":3}]', '[{"name":"ACRYLIC-LENS-BLOW-MOLD-REVA.pdf","fileType":"PDF","fileSize":"3.2 MB","uploadDate":"2026-06-13","uploadedBy":"Robert Vance","designVersion":"Rev A"}]', '[]', '2026-06-13', 'Robert Vance'),
('ITM-CAM-PART-SPACER', 'Machined Plastic Spacer Ring', 'CAM-PART-SPACER', 'In-house lathe-turned acetal spacer ring to isolate acrylic dome-lens and aluminium chassis.', '[{"materialId":"MAT-2026-0008","name":"Acetal Polymer Round Lathe Rod Black","qtyNeeded":0.1}]', '[]', '[{"name":"Lathe Machining (Plastic spacer)","estimatedHours":1,"sequence":1}]', '[{"name":"LATHE-PLASTIC-SPACER-REV1.dxf","fileType":"DXF","fileSize":"850 KB","uploadDate":"2026-06-13","uploadedBy":"Robert Vance","designVersion":"Rev 1"}]', '[]', '2026-06-13', 'Robert Vance'),
('ITM-EXP-001-P1', 'Corner Mount Structural Bracket Plate', 'EXP-001-P1', 'Folded corner mounting interface plate laser cut from 3mm 5005 Aluminium sheet.', '[{"materialId":"MAT-ACT-0012","name":"Aluminium Plate Sheet 5005 H34 3mm","qtyNeeded":1}]', '[{"type":"Plate","description":"Folded Corner Mount Plate","size":"3mm Aluminium","lengthMm":250,"qty":1}]', '[{"name":"CNC Laser Aluminium Plate Profiling","estimatedHours":0.5,"sequence":1},{"name":"Manual Press Folding","estimatedHours":0.5,"sequence":2}]', '[{"name":"EXP-1-BRACKET-PLATE-REVA.dxf","fileType":"DXF","fileSize":"1.4 MB","uploadDate":"2026-06-20","uploadedBy":"Robert Vance","designVersion":"Rev A"}]', '[]', '2026-06-20', 'Robert Vance'),
